 before=s;GrowthTacticLessonClosure end;end.started_fact_id="tactic_lesson:3";end.action_id="action:2";end.reason="student_cancelled";end.tick=7;end.fee_released=101;s.closures.insert("tactic_lesson:5",end);c.state().facts.insert("tactic_lesson:5",{"tactic_lesson:5","tactic_lesson_closed","growth_tactic_lessons"});c.state().identity.revision=6;auto cancel=cache(c,2,"result:6","tactic_lesson_cancel",Done{});diff=growth_tactic_lesson_new_sources(before,s);check(diff.ok&&diff.value.closures==std::vector<StableId>{"tactic_lesson:5"},"only actual new closure selected");auto copied=*cancel;check(!bind_growth_tactic_lesson_result_in_candidate(c,s,diff.value,"student",2,copied,7).ok,"copied result is not cache object");check(s.closures.find("tactic_lesson:5")->commit.result_id.empty(),"failed binding leaves no write");check(bind_growth_tactic_lesson_result_in_candidate(c,s,diff.value,"student",2,*cancel,7).ok,"exact zero time cancellation binds");
